begin;
create extension if not exists pgtap with schema extensions;
do $$ declare f record; begin
 for f in select p.oid::regprocedure signature from pg_proc p join pg_depend d on d.objid=p.oid and d.classid='pg_proc'::regclass join pg_extension e on e.oid=d.refobjid and d.refclassid='pg_extension'::regclass where e.extname='pgtap' and d.deptype='e' loop execute format('grant execute on function %s to anon,authenticated,service_role',f.signature); end loop;
end $$;
select no_plan();
insert into auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select ('98000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'authenticated','authenticated','official-'||n||'@example.test',case when n=6 then null else now() end,'{}','{}',now(),now() from generate_series(1,6) n;
insert into auth.sessions(id,user_id,created_at,updated_at) select id,id,now(),now() from auth.users where id::text like '98000000-%';
insert into public.committee_members(user_id,role) values('98000000-0000-4000-8000-000000000001','committee_chair'),('98000000-0000-4000-8000-000000000002','verification_officer');
set local request.jwt.claim.sub='98000000-0000-4000-8000-000000000001';
set local request.jwt.claims='{"session_id":"98000000-0000-4000-8000-000000000001"}';
set local role authenticated;
select ok(public.has_committee_role(array['committee_chair']::public.committee_role[]),'unbound chair retains committee authority');
select is(public.has_student_access(),false,'committee authority does not grant voter access');
select throws_ok($$select public.stage_official_register('{"classification":"official"}')$$,'P0001',null,'real membership activation remains disabled');
select set_config('test.register_id',public.stage_official_register(jsonb_build_object('reason','Rollback-only source under separate review','title','Synthetic approved source','classification','synthetic','membershipOpens',now()-interval '3 days','membershipCloses',now()-interval '2 days','activationOpens',now()-interval '1 hour','activationCloses',now()+interval '1 day','fileName','official.csv','sourceSha256',repeat('a',64),'requestKey','98100000-0000-4000-8000-000000000001','rows',jsonb_build_array(jsonb_build_object('fullName','Official Student Three','registrationNumber','OFF-003','email','official-3@example.test'),jsonb_build_object('fullName','Official Student Four','registrationNumber','OFF-004','email','official-4@example.test'))))::text,true);
-- If earlier browser fixtures exist, this rollback-only source is a reviewed
