reset role;
update public.official_registers set parent_id=(select id from public.official_registers where status='locked' and classification='synthetic' order by approved_at desc,id desc limit 1),created_by=case when exists(select 1 from public.official_registers where status='locked' and classification='synthetic') then '98000000-0000-4000-8000-000000000002'::uuid else created_by end,reason='Rollback-only independently reviewed synthetic source' where id=current_setting('test.register_id')::uuid;
