select is((public.get_register_preview(current_setting('test.register_id')::uuid,1)->>'total')::integer,2,'preview contains complete staged population');
select is((public.get_register_preview(current_setting('test.register_id')::uuid,1)->>'invalid')::integer,0,'required official identity fields validate');
select is((select count(*) from public.official_register_entries where register_id=current_setting('test.register_id')::uuid),0::bigint,'upload alone creates no authoritative entries');
