set local request.jwt.claims='{"session_id":"98000000-0000-4000-8000-000000000003"}';
select is(public.bind_official_voter('OFF-003')->>'activated','false','staged entry cannot activate');
select is((select count(*) from public.official_registers),0::bigint,'student cannot read private snapshots');
select throws_ok($$select public.get_register_preview(current_setting('test.register_id')::uuid,1)$$,'P0001',null,'student cannot request preview through RPC');
select throws_ok($$select public.approve_official_register(current_setting('test.register_id')::uuid,repeat('a',64))$$,'P0001',null,'student cannot approve register');
set local request.jwt.claim.sub='98000000-0000-4000-8000-000000000002';
set local request.jwt.claims='{"session_id":"98000000-0000-4000-8000-000000000002"}';
select throws_ok($$select public.approve_official_register(current_setting('test.register_id')::uuid,repeat('a',64))$$,'P0001',null,'verification officer cannot approve register');
