set local request.jwt.claims='{"session_id":"98000000-0000-4000-8000-000000000001"}';
select lives_ok($$select public.approve_official_register(current_setting('test.register_id')::uuid,(public.get_register_preview(current_setting('test.register_id')::uuid,1)->>'snapshot'))$$,'authorized chair approves complete snapshot');
select lives_ok($$select public.approve_official_register(current_setting('test.register_id')::uuid,(public.get_register_preview(current_setting('test.register_id')::uuid,1)->>'snapshot'))$$,'same approval retry is idempotent');
select is((select status from public.official_registers where id=current_setting('test.register_id')::uuid),'locked','register locks after approval');
