select is((select count(*) from public.voter_bindings where user_id='98000000-0000-4000-8000-000000000003'),1::bigint,'only one durable binding');
select throws_ok($$update public.official_registers set rows_snapshot='[]' where id=current_setting('test.register_id')::uuid$$,'P0001',null,'locked snapshot trigger rejects even operator accidental edit');
select throws_ok($$delete from public.voter_bindings where user_id='98000000-0000-4000-8000-000000000003'$$,'P0001',null,'binding tombstone cannot be freed for duplicate claim');
set local role authenticated;
set local request.jwt.claim.sub='98000000-0000-4000-8000-000000000001';
