select set_config('test.email_correction',public.propose_register_correction(current_setting('test.register_id')::uuid,'OFF-004','Corrected Student Four','corrected-4@example.test','OFF-004','Independent synthetic email correction')::text,true);
set local request.jwt.claim.sub='98000000-0000-4000-8000-000000000001';
