set local request.jwt.claim.sub='98000000-0000-4000-8000-000000000004';
set local request.jwt.claims='{"session_id":"98000000-0000-4000-8000-000000000004"}';
select is(public.has_student_access(),false,'changed email requires a fresh official-register ownership proof');
