reset role;
select is((select proof_email from public.voter_bindings where user_id='98000000-0000-4000-8000-000000000004'),'official-4@example.test','original permanent binding evidence is unchanged');
select is((select count(*) from public.voter_binding_proofs where user_id='98000000-0000-4000-8000-000000000004'),2::bigint,'email correction appends proofs without freeing identity claim');
