select is(public.is_active_session(),true,'suspension test retains the old valid Auth session');
select is(public.has_student_access(),false,'membership suspension invalidates authorization independently of Auth');
select is(public.get_my_membership()->>'active','false','suspended member receives no private membership projection');
select throws_ok($$select public.update_candidate_draft(gen_random_uuid(),repeat('b',40),repeat('m',100))$$,'P0001',null,'suspended student cannot use candidate RPC');
select is(public.bind_official_voter('OFF-003')->>'activated','false','suspension does not free or reactivate binding');
