insert into public.elections(id,title,nominations_start,nominations_end,voting_start,voting_end,created_by) values('98300000-0000-4000-8000-000000000001','Synthetic preapproved plan',now()-interval '1 day',now()+interval '1 day',now()+interval '2 days',now()+interval '3 days','98000000-0000-4000-8000-000000000001');
